// ── Types ────────────────────────────────────────────────────────────────────

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

interface PEStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

// ── Utilities ────────────────────────────────────────────────────────────────

function lbl(
  g: Gsel | Sel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; font?: string; anchor?: 'start' | 'middle' | 'end' } = {},
): void { drawLabel(g as Sel, x, y, text, opts); }

function arrowDown(g: Gsel, cx: number, y1: number, y2: number): void {
  drawArrow(g as Sel, cx, y1, cx, y2, { color: '#94a3b8' });
}

function makeLcg(seed: number): () => number {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) & 0xffffffff; return (s >>> 0) / 0xffffffff; };
}

function hexA(hex: string, a: number): string {
  const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${a.toFixed(3)})`;
}

function arrowMarker(g: Gsel, color: string): string {
  const id = `pe-arr-${color.replace('#', '')}`;
  const svg = (g.node() as SVGElement)?.ownerSVGElement;
  if (svg && !svg.querySelector(`#${id}`)) {
    const defs = d3.select(svg).selectAll('defs').data([null]).join('defs');
    (defs as unknown as Gsel).append('marker').attr('id', id)
      .attr('viewBox', '0 -5 10 10').attr('refX', 9).attr('refY', 0)
      .attr('markerWidth', 6).attr('markerHeight', 6).attr('orient', 'auto')
      .append('path').attr('d', 'M0,-5L10,0L0,5').attr('fill', color);
  }
  return `url(#${id})`;
}

function divColor(v: number): string {
  const c = Math.max(-1, Math.min(1, v));
  if (c < 0) return `rgba(59,130,246,${(Math.abs(c) * 0.75).toFixed(3)})`;
  return `rgba(239,68,68,${(c * 0.75).toFixed(3)})`;
}

function posColors(): string[] {
  return ['#6366f1', '#d97706', '#16a34a', '#dc2626', '#7c3aed', '#0891b2'];
}

// ── Shared header ────────────────────────────────────────────────────────────

function drawHeader(g: Gsel, cx: number, y: number, title: string, sub: string): number {
  lbl(g, cx, y, title, { size: 15, weight: '700', color: 'var(--text)' });
  y += 18;
  lbl(g, cx, y, sub, { size: 10, color: 'var(--text-muted)' });
  return y + 22;
}

