// ── Main entry ───────────────────────────────────────────────────────────────

export function renderPositionalEncodingDetailed(
  g: Sel, params: Record<string, number | string>,
  _meta: ComponentDef, _graph: ComputationGraph,
): { width: number; height: number; steps: PEStep[] } {
  const variant = String(params.variant ?? 'rope');
  const seqLen = Number(params.seq_len) || 128;
  const dModel = Number(params.d_model) || 512;
  const W = 720;

  switch (variant) {
    case 'sinusoidal': return renderSinusoidal(g as Gsel, seqLen, dModel, W);
    case 'alibi':      return renderALiBi(g as Gsel, seqLen, dModel, W);
    case 'learned':    return renderLearned(g as Gsel, seqLen, dModel, W);
    case 'yarn':       return renderYaRN(g as Gsel, seqLen, dModel, W);
    default:           return renderRoPE(g as Gsel, seqLen, dModel, W);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// RoPE
// ══════════════════════════════════════════════════════════════════════════════

function renderRoPE(g: Gsel, seqLen: number, dModel: number, W: number)
  : { width: number; height: number; steps: PEStep[] } {
  const cx = W / 2;
  let y = 28;
  const base = 10000;

  y = drawHeader(g, cx, y, 'Positional Encoding — RoPE', `d_model=${dModel}  seq_len=${seqLen}  base=${base}`);

  // Input tensor
  drawTensor(g as unknown as Sel, cx - 120, y, 240, 28, `q, k: [B, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 48;

  // Step 1: Input Q/K
  const s1 = g.append('g').attr('class', 'step-node step-rope-input').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 130, y, 260, 40, 'Input Q/K Vectors', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'q, k from linear projection' });
  y += 56;

  // Q/K strips
  const stripW = 140, stripH = 14;
  lbl(s1 as Sel, cx - 80, y + stripH / 2, 'q', { size: 9, weight: '700', color: '#1976d2', anchor: 'end' });
  drawMiniStrip(s1, cx - 70, y, stripW, stripH, '#1976d2', 42);
  lbl(s1 as Sel, cx - 70 + stripW + 4, y + stripH / 2, `[${seqLen}, ${dModel}]`, { size: 7, font: 'monospace', color: '#1976d2', anchor: 'start' });

  lbl(s1 as Sel, cx - 80, y + 22 + stripH / 2, 'k', { size: 9, weight: '700', color: '#7c3aed', anchor: 'end' });
  drawMiniStrip(s1, cx - 70, y + 22, stripW, stripH, '#7c3aed', 77);
  lbl(s1 as Sel, cx - 70 + stripW + 4, y + 22 + stripH / 2, `[${seqLen}, ${dModel}]`, { size: 7, font: 'monospace', color: '#7c3aed', anchor: 'start' });
  y += 56;

  // Step 2: Split into pairs
  const s2 = g.append('g').attr('class', 'step-node step-rope-pairs').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 130, y, 260, 40, 'Reshape into d/2 Pairs', { step: 2, fill: '#dbeafe', stroke: '#1976d2', formula: `[seq, ${dModel}] → [seq, ${dModel / 2}, 2]` });
  y += 56;

  drawPairSplit(s2, cx - 200, y, dModel);
  y += 58;

  // Step 3: Frequency table
  const s3 = g.append('g').attr('class', 'step-node step-rope-freq').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 130, y, 260, 40, 'Frequency Table θ_i', { step: 3, fill: '#ede9fe', stroke: '#7c3aed', formula: 'θ_i = base^(-2i/d)' });
  y += 56;

  y = drawFrequencyTable(s3, cx - 160, y, dModel, base);
  y += 16;

  // Step 4: 2D Rotation (centerpiece)
  const s4 = g.append('g').attr('class', 'step-node step-rope-rotate').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 150, y, 300, 40, '2D Rotation per Position', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'R(θ_i · pos) · [x_{2i}, x_{2i+1}]^T' });
  y += 56;

  // Part A: 3 rotation planes (different pairs, fixed position)
  lbl(s4 as Sel, cx, y, 'Rotation Planes (position m = 3)', { size: 9, weight: '600', color: '#d97706' });
  y += 20;

  const planeR = 48;
  const planeW = 155;
  const planePairs = [0, 1, 3];
  const planeX0 = cx - (planePairs.length * planeW) / 2;
  const posForPlane = 3;

  planePairs.forEach((pairIdx, idx) => {
    const theta = Math.pow(base, -2 * pairIdx / dModel);
    const pcx = planeX0 + idx * planeW + planeW / 2;
    const pcy = y + planeR + 8;
    const angle = theta * posForPlane;
    const origAngle = 0.65;
    draw2DPlane(s4, pcx, pcy, planeR, origAngle, origAngle + angle, `pair i=${pairIdx}`, theta);
  });
  y += planeR * 2 + 46;

  // Part B: Clock diagram (same pair, multiple positions)
  lbl(s4 as Sel, cx, y, 'Clock Diagram — pair i=0 across positions', { size: 9, weight: '600', color: '#d97706' });
  y += 18;

  const clockR = 68;
  const clockCx = cx;
  const clockCy = y + clockR + 8;
  drawClockDiagram(s4, clockCx, clockCy, clockR, 1.0, 6);
  y += clockR * 2 + 140;

  // Step 5: Reassemble
  const s5 = g.append('g').attr('class', 'step-node step-rope-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 140, y, 280, 40, 'Reassemble Rotated Vectors', { step: 5, fill: '#fee2e2', stroke: '#dc2626', formula: `[seq, ${dModel / 2}, 2] → [seq, ${dModel}]` });
  y += 56;

  drawTensor(g as unknown as Sel, cx - 130, y, 260, 28, `q_rot, k_rot: [B, ${seqLen}, ${dModel}]`, '#fee2e2', '#dc2626');
  y += 48;

  // Params
  lbl(g, cx, y, 'Params: 0 (fixed rotation, no learnable parameters)', { size: 10, color: '#1976d2', weight: '600' });
  y += 16;
  lbl(g, cx, y, `FLOPs: O(${seqLen} × ${dModel}) for cos/sin + rotation`, { size: 10, color: 'var(--text-muted)' });
  y += 24;

  // Explanations
  y = drawExplanation(g as Sel, 60, y, W - 120,
    'RoPE encodes relative position directly into attention scores via rotation. ' +
    'When computing Q_rot^T · K_rot, the absolute positions cancel out, leaving only the ' +
    'relative distance (m−n). This is fundamentally different from additive PE which encodes absolute position.',
    'insight');
  y += 6;
  y = drawExplanation(g as Sel, 60, y, W - 120,
    'The multi-frequency design means low-index pairs capture fine-grained local position ' +
    '(fast rotation) while high-index pairs capture coarse global position (slow rotation). ' +
    'This is analogous to a Fourier basis with geometrically spaced frequencies.',
    'perf');
  y += 6;

  drawComponentLink(g as Sel, cx - 70, y, 140, 24, 'attention', 'View Attention ↗', { fill: '#e3f2fd', stroke: '#1976d2' });
  y += 40;

  y = drawCodeAnnotation(g as Sel, 60, y, W - 120,
    'RoPE — Rotary Position Embedding (Su et al. 2021)',
    ['Rotates pairs of dimensions by angle θ_i × position.',
     'Dot product of rotated Q/K encodes relative position.',
     `Frequencies: θ_i = ${base}^(-2i/${dModel}).`],
    ['theta_i = 1.0 / (base ** (2*i / d_model))',
     'angle = pos * theta_i',
     '',
     'def apply_rope(x, pos):',
     '    cos_val, sin_val = cos(angle), sin(angle)',
     '    x0, x1 = x[..., 0::2], x[..., 1::2]',
     '    return stack(x0*cos - x1*sin, x0*sin + x1*cos)']);

  return { width: W, height: y + 20, steps: ROPE_STEPS };
}

// ── RoPE drawing helpers ─────────────────────────────────────────────────────

function drawMiniStrip(g: Gsel, x: number, y: number, w: number, h: number, color: string, seed: number): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const cols = 20;
  const cw = w / cols;
  const rand = makeLcg(seed);
  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 2)
    .attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1);
  for (let c = 0; c < cols; c++) {
    const v = rand();
    grp.append('rect').attr('x', c * cw + 0.3).attr('y', 0.3)
      .attr('width', cw - 0.6).attr('height', h - 0.6)
      .attr('fill', hexA(color, 0.08 + v * 0.5));
  }
}

function drawPairSplit(g: Gsel, x: number, y: number, dModel: number): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const cellW = 36, cellH = 24, nCells = 10, gap = 4;
  const colors = posColors();
  const rand = makeLcg(314);

  for (let i = 0; i < nCells; i++) {
    const cx = i * (cellW + gap);
    const v = (rand() * 2 - 1).toFixed(2);
    const pairColor = colors[i % colors.length];
    grp.append('rect').attr('x', cx).attr('y', 0).attr('width', cellW).attr('height', cellH).attr('rx', 4)
      .attr('fill', hexA(pairColor, 0.12)).attr('stroke', pairColor).attr('stroke-width', 1.2);
    lbl(grp as Sel, cx + cellW / 2, cellH / 2 - 4, `x${i}`, { size: 7, weight: '600', color: pairColor });
    lbl(grp as Sel, cx + cellW / 2, cellH / 2 + 6, v, { size: 6, font: 'monospace', color: 'var(--text-muted)' });
  }

  // Brackets for pairs
  for (let p = 0; p < Math.min(4, nCells / 2); p++) {
    const px = p * 2 * (cellW + gap);
    const pw = 2 * cellW + gap;
    grp.append('line').attr('x1', px).attr('y1', cellH + 4).attr('x2', px + pw).attr('y2', cellH + 4)
      .attr('stroke', '#d97706').attr('stroke-width', 1);
    grp.append('line').attr('x1', px).attr('y1', cellH + 2).attr('x2', px).attr('y2', cellH + 6)
      .attr('stroke', '#d97706').attr('stroke-width', 1);
    grp.append('line').attr('x1', px + pw).attr('y1', cellH + 2).attr('x2', px + pw).attr('y2', cellH + 6)
      .attr('stroke', '#d97706').attr('stroke-width', 1);
    lbl(grp as Sel, px + pw / 2, cellH + 14, `pair ${p}`, { size: 6, color: '#d97706', weight: '600' });
  }
  lbl(grp as Sel, nCells * (cellW + gap) / 2, cellH + 28, `→ ${dModel / 2} pairs`, { size: 8, color: '#d97706', weight: '600' });
}

function drawFrequencyTable(g: Gsel, x: number, y: number, dModel: number, base: number): number {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const nRows = 8;
  const rowH = 22;
  const colW = [50, 120, 100];
  const totalW = colW.reduce((a, b) => a + b, 0);

  // Header
  const hdrH = 20;
  grp.append('rect').attr('width', totalW).attr('height', hdrH).attr('rx', 4)
    .attr('fill', '#ede9fe').attr('stroke', '#7c3aed').attr('stroke-width', 1);
  lbl(grp as Sel, colW[0] / 2, hdrH / 2, 'Pair i', { size: 7, weight: '700', color: '#7c3aed' });
  lbl(grp as Sel, colW[0] + colW[1] / 2, hdrH / 2, 'θ_i = base^(-2i/d)', { size: 7, weight: '700', color: '#7c3aed' });
  lbl(grp as Sel, colW[0] + colW[1] + colW[2] / 2, hdrH / 2, 'Value', { size: 7, weight: '700', color: '#7c3aed' });

  let yy = hdrH;
  const colors = posColors();
  for (let i = 0; i < nRows; i++) {
    const theta = Math.pow(base, -2 * i / dModel);
    const color = colors[i % colors.length];
    grp.append('rect').attr('y', yy).attr('width', totalW).attr('height', rowH)
      .attr('fill', hexA(color, 0.06)).attr('stroke', 'var(--border)').attr('stroke-width', 0.5);

    lbl(grp as Sel, colW[0] / 2, yy + rowH / 2, `${i}`, { size: 8, weight: '700', color });
    lbl(grp as Sel, colW[0] + colW[1] / 2, yy + rowH / 2,
      `${base}^(${-2 * i}/${dModel})`, { size: 7, font: 'monospace', color: 'var(--text)' });

    const valStr = theta >= 0.001 ? theta.toFixed(4) : theta.toExponential(2);
    lbl(grp as Sel, colW[0] + colW[1] + colW[2] / 2, yy + rowH / 2, valStr,
      { size: 8, font: 'monospace', weight: '600', color });

    // Frequency bar (visual indicator)
    const barMaxW = 60;
    const barW = Math.max(2, barMaxW * (Math.log10(theta + 1e-10) + 5) / 5);
    grp.append('rect').attr('x', colW[0] + colW[1] + colW[2] + 6).attr('y', yy + 4)
      .attr('width', barW).attr('height', rowH - 8).attr('rx', 2)
      .attr('fill', hexA(color, 0.35));

    yy += rowH;
  }
  lbl(grp as Sel, totalW / 2, yy + 12, '⋮ (d/2 pairs total)', { size: 8, color: 'var(--text-muted)' });

  return y + yy + 24;
}

function draw2DPlane(
  g: Gsel, cx: number, cy: number, r: number,
  origAngle: number, rotAngle: number,
  label: string, theta: number,
): void {
  const grp = g.append('g');

  // Background circle
  grp.append('circle').attr('cx', cx).attr('cy', cy).attr('r', r)
    .attr('fill', 'var(--surface)').attr('stroke', '#e0e0e0').attr('stroke-width', 1);

  // Axes
  grp.append('line').attr('x1', cx - r).attr('y1', cy).attr('x2', cx + r).attr('y2', cy)
    .attr('stroke', '#ccc').attr('stroke-width', 0.5);
  grp.append('line').attr('x1', cx).attr('y1', cy - r).attr('x2', cx).attr('y2', cy + r)
    .attr('stroke', '#ccc').attr('stroke-width', 0.5);

  // Original vector (blue)
  const arrowLen = r * 0.75;
  const ox = cx + arrowLen * Math.cos(origAngle);
  const oy = cy - arrowLen * Math.sin(origAngle); // SVG y inverted
  grp.append('line').attr('x1', cx).attr('y1', cy).attr('x2', ox).attr('y2', oy)
    .attr('stroke', '#1976d2').attr('stroke-width', 2).attr('marker-end', arrowMarker(g, '#1976d2'));

  // Rotated vector (orange)
  const rx = cx + arrowLen * Math.cos(rotAngle);
  const ry = cy - arrowLen * Math.sin(rotAngle);
  grp.append('line').attr('x1', cx).attr('y1', cy).attr('x2', rx).attr('y2', ry)
    .attr('stroke', '#d97706').attr('stroke-width', 2).attr('marker-end', arrowMarker(g, '#d97706'));

  // Arc between them
  if (Math.abs(rotAngle - origAngle) > 0.05) {
    // SVG arc: negate angles for SVG y-inversion
    drawRotationArc(grp as Sel, cx, cy, r * 0.45, -origAngle, -rotAngle, { color: '#d97706', showArrow: true });
  }

  // Labels
  lbl(grp as Sel, cx, cy + r + 14, label, { size: 8, weight: '600', color: '#333' });
  const thetaStr = theta >= 0.001 ? theta.toFixed(3) : theta.toExponential(1);
  lbl(grp as Sel, cx, cy + r + 24, `θ=${thetaStr}`, { size: 6, font: 'monospace', color: '#7c3aed' });
}

function drawClockDiagram(
  g: Gsel, cx: number, cy: number, r: number,
  theta: number, nPositions: number,
): void {
  const grp = g.append('g');
  const colors = posColors();
  const arrowLen = r * 0.82;

  // Background circle
  grp.append('circle').attr('cx', cx).attr('cy', cy).attr('r', r + 4)
    .attr('fill', 'var(--surface)').attr('stroke', '#e0e0e0').attr('stroke-width', 1);

  // Axes
  grp.append('line').attr('x1', cx - r).attr('y1', cy).attr('x2', cx + r).attr('y2', cy)
    .attr('stroke', '#ddd').attr('stroke-width', 0.5);
  grp.append('line').attr('x1', cx).attr('y1', cy - r).attr('x2', cx).attr('y2', cy + r)
    .attr('stroke', '#ddd').attr('stroke-width', 0.5);

  // Draw vectors for each position
  for (let m = 0; m < nPositions; m++) {
    const angle = theta * m;
    const color = colors[m % colors.length];
    const ex = cx + arrowLen * Math.cos(angle);
    const ey = cy - arrowLen * Math.sin(angle);

    grp.append('line').attr('x1', cx).attr('y1', cy).attr('x2', ex).attr('y2', ey)
      .attr('stroke', color).attr('stroke-width', 2)
      .attr('marker-end', arrowMarker(g, color))
      .attr('opacity', 0.85);

    // Position label at tip
    const lx = cx + (arrowLen + 16) * Math.cos(angle);
    const ly = cy - (arrowLen + 16) * Math.sin(angle);
    lbl(grp as Sel, lx, ly, `m=${m}`, { size: 7, weight: '600', color });
  }

  // Legend
  lbl(grp as Sel, cx, cy + r + 18, 'Each arrow = same vector pair at different positions', { size: 8, color: '#d97706', weight: '600' });
  lbl(grp as Sel, cx, cy + r + 30, `Rotation angle per position: θ = ${theta.toFixed(2)} rad`, { size: 7, font: 'monospace', color: 'var(--text-muted)' });
}

// ══════════════════════════════════════════════════════════════════════════════
// Sinusoidal
// ══════════════════════════════════════════════════════════════════════════════

function renderSinusoidal(g: Gsel, seqLen: number, dModel: number, W: number)
  : { width: number; height: number; steps: PEStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Positional Encoding — Sinusoidal', `d_model=${dModel}  seq_len=${seqLen}`);

  drawTensor(g as unknown as Sel, cx - 110, y, 220, 28, `x: [B, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 48;

  // Step 1: PE table heatmap
  const s1 = g.append('g').attr('class', 'step-node step-sin-table').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 140, y, 280, 40, 'Generate PE Table (sin/cos)', { step: 1, fill: '#dbeafe', stroke: '#2563eb', formula: 'PE(pos,2i)=sin, PE(pos,2i+1)=cos' });
  y += 56;

  const hRows = 16, hCols = 24, hCellW = 16, hCellH = 13;
  const hmX = cx - (hCols * hCellW) / 2;
  drawSinHeatmap(s1, hmX, y, hRows, hCols, hCellW, hCellH, dModel);
  lbl(s1 as Sel, hmX - 6, y + (hRows * hCellH) / 2, 'pos ↑', { size: 7, color: '#2563eb', anchor: 'end', weight: '600' });
  lbl(s1 as Sel, hmX + (hCols * hCellW) / 2, y + hRows * hCellH + 12, 'dimension → (high freq at left, low freq at right)', { size: 7, color: '#2563eb', weight: '600' });
  y += hRows * hCellH + 30;

  // Step 2: Wave plots
  const s2 = g.append('g').attr('class', 'step-node step-sin-waves').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 40, 'Wave Pattern: High → Low Frequency', { step: 2, fill: '#ede9fe', stroke: '#7c3aed', formula: 'λ_i = 2π · base^(2i/d)' });
  y += 56;

  const wavePairs = [0, 2, 5];
  const waveLabels = wavePairs.map(pairI => {
    const lambda = 2 * Math.PI * Math.pow(10000, 2 * pairI / dModel);
    const lambdaStr = lambda < 100 ? lambda.toFixed(1) : lambda < 10000 ? lambda.toFixed(0) : `${(lambda / 1000).toFixed(0)}K`;
    return `dim ${pairI*2},${pairI*2+1} (λ≈${lambdaStr})`;
  });
  const waveW = 180, waveH = 55, waveGap = 20;
  const waveX0 = cx - (wavePairs.length * waveW + (wavePairs.length - 1) * waveGap) / 2;
  wavePairs.forEach((pairI, idx) => {
    const wx = waveX0 + idx * (waveW + waveGap);
    drawWavePlot(s2, wx, y, waveW, waveH, pairI, dModel, waveLabels[idx]);
  });
  y += waveH + 30;

  // Step 3: Addition
  const s3 = g.append('g').attr('class', 'step-node step-sin-add').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);

  const addY = y;
  // Embedding box
  drawTensor(g as unknown as Sel, cx - 200, addY, 120, 28, 'e: embed', '#e8f5e9', '#4caf50');
  // Arrow to +
  s3.append('line').attr('x1', cx - 80).attr('y1', addY + 14).attr('x2', cx - 18).attr('y2', addY + 14)
    .attr('stroke', '#4caf50').attr('stroke-width', 1.5).attr('marker-end', arrowMarker(g, '#4caf50'));
  // + circle
  s3.append('circle').attr('cx', cx).attr('cy', addY + 14).attr('r', 14)
    .attr('fill', '#dbeafe').attr('stroke', '#2563eb').attr('stroke-width', 2);
  lbl(s3 as Sel, cx, addY + 14, '+', { size: 16, weight: '700', color: '#2563eb' });
  // PE box above
  drawTensor(g as unknown as Sel, cx - 60, addY - 40, 120, 28, 'PE: sin/cos', '#dbeafe', '#2563eb');
  s3.append('line').attr('x1', cx).attr('y1', addY - 12).attr('x2', cx).attr('y2', addY - 2)
    .attr('stroke', '#2563eb').attr('stroke-width', 1.5).attr('marker-end', arrowMarker(g, '#2563eb'));
  // Arrow from +
  s3.append('line').attr('x1', cx + 14).attr('y1', addY + 14).attr('x2', cx + 62).attr('y2', addY + 14)
    .attr('stroke', '#16a34a').attr('stroke-width', 1.5).attr('marker-end', arrowMarker(g, '#16a34a'));
  // Output
  drawTensor(g as unknown as Sel, cx + 64, addY, 120, 28, 'x = e + PE', '#dcfce7', '#16a34a');
  y += 60;

  // Params
  lbl(g, cx, y, 'Params: 0 (fixed sin/cos, no learnable parameters)', { size: 10, color: '#2563eb', weight: '600' });
  y += 16;
  lbl(g, cx, y, `FLOPs: O(${seqLen} × ${dModel}) for sin/cos computation`, { size: 10, color: 'var(--text-muted)' });
  y += 24;

  y = drawExplanation(g as Sel, 60, y, W - 120,
    'Sinusoidal PE uses fixed sin/cos functions at geometrically spaced frequencies. ' +
    'The model cannot learn the position representation, but the fixed basis generalizes to any sequence length.',
    'insight');
  y += 6;

  y = drawCodeAnnotation(g as Sel, 60, y, W - 120,
    'Sinusoidal PE — Attention Is All You Need (Vaswani et al. 2017)',
    ['Fixed frequency patterns, no learned parameters.',
     'Even dims use sin, odd dims use cos.',
     `PE shape: [${seqLen}, ${dModel}].`],
    ['pos = torch.arange(seq_len).unsqueeze(1)',
     'dim = torch.arange(0, d_model, 2)',
     'angles = pos / 10000 ** (dim / d_model)',
     'PE[:, 0::2] = sin(angles)',
     'PE[:, 1::2] = cos(angles)',
     'x = embed + PE']);

  return { width: W, height: y + 20, steps: SIN_STEPS };
}

function drawSinHeatmap(
  g: Gsel, x: number, y: number,
  rows: number, cols: number, cellW: number, cellH: number, dModel: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  grp.append('rect').attr('width', cols * cellW).attr('height', rows * cellH).attr('rx', 4)
    .attr('fill', 'var(--surface)').attr('stroke', '#94a3b8').attr('stroke-width', 1);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const pairIdx = Math.floor(c / 2);
      const theta = Math.pow(10000, -2 * pairIdx / dModel);
      const isEven = c % 2 === 0;
      const val = isEven ? Math.sin(r * theta) : Math.cos(r * theta);
      grp.append('rect').attr('x', c * cellW).attr('y', r * cellH)
        .attr('width', cellW).attr('height', cellH)
        .attr('fill', divColor(val)).attr('stroke', 'var(--border)').attr('stroke-width', 0.2);
    }
  }
}

function drawWavePlot(
  g: Gsel, x: number, y: number, w: number, h: number,
  pairIdx: number, dModel: number, label: string,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 4)
    .attr('fill', 'var(--surface)').attr('stroke', '#e0e0e0').attr('stroke-width', 1);

  const theta = Math.pow(10000, -2 * pairIdx / dModel);
  const nPoints = 60;
  const maxPos = Math.min(64, Math.max(20, Math.ceil(2 * Math.PI / theta * 2)));
  const points: [number, number][] = [];
  for (let i = 0; i <= nPoints; i++) {
    const pos = (i / nPoints) * maxPos;
    const val = Math.sin(pos * theta);
    points.push([4 + (i / nPoints) * (w - 8), h / 2 - val * (h / 2 - 4)]);
  }
  const line = d3.line<[number, number]>().x(d => d[0]).y(d => d[1]);
  grp.append('path').datum(points).attr('d', line)
    .attr('fill', 'none').attr('stroke', '#7c3aed').attr('stroke-width', 1.5);

  // Zero line
  grp.append('line').attr('x1', 4).attr('y1', h / 2).attr('x2', w - 4).attr('y2', h / 2)
    .attr('stroke', '#ccc').attr('stroke-width', 0.5).attr('stroke-dasharray', '2,2');

  lbl(grp as Sel, w / 2, h + 12, label, { size: 7, color: '#7c3aed', weight: '600' });
}

// ══════════════════════════════════════════════════════════════════════════════
// ALiBi
// ══════════════════════════════════════════════════════════════════════════════

function renderALiBi(g: Gsel, seqLen: number, dModel: number, W: number)
  : { width: number; height: number; steps: PEStep[] } {
  const cx = W / 2;
  let y = 28;
  const nHeads = 8;

  y = drawHeader(g, cx, y, 'Positional Encoding — ALiBi', `d_model=${dModel}  seq_len=${seqLen}  n_heads=${nHeads}`);

  drawTensor(g as unknown as Sel, cx - 110, y, 220, 28, `x: [B, ${seqLen}, ${dModel}]`, '#f3e5f5', '#7b1fa2');
  y += 48;

  // Step 1: Head slopes
  const s1 = g.append('g').attr('class', 'step-node step-alibi-slopes').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 140, y, 280, 40, 'Compute Head Slopes', { step: 1, fill: '#f3e5f5', stroke: '#7b1fa2', formula: 'm_h = 2^(-8h/H)' });
  y += 56;

  drawSlopeBars(s1, cx - 180, y, nHeads);
  y += 80;

  // Step 2: Bias matrices
  const s2 = g.append('g').attr('class', 'step-node step-alibi-matrix').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 40, 'Build Distance Bias Matrix', { step: 2, fill: '#fef3c7', stroke: '#d97706', formula: 'bias[i,j] = -m_h · |i - j|' });
  y += 56;

  const matSize = 8;
  const matCellW = 22;
  const matGap = 30;
  const headsToShow = [0, 3, 7];
  const matX0 = cx - (headsToShow.length * matSize * matCellW + (headsToShow.length - 1) * matGap) / 2;
  headsToShow.forEach((h, idx) => {
    const mx = matX0 + idx * (matSize * matCellW + matGap);
    const slope = Math.pow(2, -8 * (h + 1) / nHeads);
    drawBiasMatrix(s2, mx, y, matSize, matCellW, slope);
    lbl(s2 as Sel, mx + (matSize * matCellW) / 2, y + matSize * matCellW + 14,
      `head ${h} (m=${slope.toFixed(3)})`, { size: 7, weight: '600', color: '#d97706' });
  });
  y += matSize * matCellW + 36;

  // Step 3: Add to attention scores
  const s3 = g.append('g').attr('class', 'step-node step-alibi-add').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 140, y, 280, 40, 'Add Bias to Attention Scores', { step: 3, fill: '#dcfce7', stroke: '#16a34a', formula: 'scores = QK^T + bias (no params)' });
  y += 56;

  drawTensor(g as unknown as Sel, cx - 200, y, 100, 28, 'QK^T', '#e3f2fd', '#1976d2');
  s3.append('line').attr('x1', cx - 100).attr('y1', y + 14).attr('x2', cx - 18).attr('y2', y + 14)
    .attr('stroke', '#1976d2').attr('stroke-width', 1.5).attr('marker-end', arrowMarker(g, '#1976d2'));
  s3.append('circle').attr('cx', cx).attr('cy', y + 14).attr('r', 12)
    .attr('fill', '#fef3c7').attr('stroke', '#d97706').attr('stroke-width', 2);
  lbl(s3 as Sel, cx, y + 14, '+', { size: 14, weight: '700', color: '#d97706' });
  s3.append('line').attr('x1', cx + 12).attr('y1', y + 14).attr('x2', cx + 62).attr('y2', y + 14)
    .attr('stroke', '#16a34a').attr('stroke-width', 1.5).attr('marker-end', arrowMarker(g, '#16a34a'));
  drawTensor(g as unknown as Sel, cx + 64, y, 120, 28, 'biased scores', '#dcfce7', '#16a34a');
  // ALiBi bias label above
  lbl(s3 as Sel, cx, y - 12, 'ALiBi bias', { size: 7, color: '#d97706', weight: '600' });
  y += 50;

  lbl(g, cx, y, 'Params: 0 (fixed distance bias, no learnable parameters)', { size: 10, color: '#7b1fa2', weight: '600' });
  y += 24;

  y = drawExplanation(g as Sel, 60, y, W - 120,
    'ALiBi adds a fixed, distance-decaying bias to attention scores. Unlike RoPE or sinusoidal PE, ' +
    'it does not modify Q or K at all — it works directly on the attention score matrix. ' +
    'Different heads attend at different distance scales.',
    'insight');
  y += 6;

  y = drawCodeAnnotation(g as Sel, 60, y, W - 120,
    'ALiBi — Train Short, Test Long (Press et al. 2022)',
    ['Fixed bias proportional to token distance.',
     'No position encoding added to embeddings.',
     `Heads: ${nHeads}, slopes from ${Math.pow(2, -8 / nHeads).toFixed(4)} to ${Math.pow(2, -8).toFixed(4)}.`],
    ['slopes = [2**(-8*h/n_heads) for h in range(n_heads)]',
     'dist = |arange(seq)[:, None] - arange(seq)[None, :]|',
     'bias = -slope * dist  # [seq, seq] per head',
     'attn = Q @ K^T / sqrt(d_k) + bias',
     'attn = softmax(attn)']);

  return { width: W, height: y + 20, steps: ALIBI_STEPS };
}

function drawSlopeBars(g: Gsel, x: number, y: number, nHeads: number): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const barW = 32, barGap = 8, maxH = 50;
  const colors = posColors();

  for (let h = 0; h < nHeads; h++) {
    const slope = Math.pow(2, -8 * (h + 1) / nHeads);
    const bx = h * (barW + barGap);
    const bh = Math.max(4, maxH * slope);
    const color = colors[h % colors.length];

    grp.append('rect').attr('x', bx).attr('y', maxH - bh).attr('width', barW).attr('height', bh).attr('rx', 3)
      .attr('fill', hexA(color, 0.3)).attr('stroke', color).attr('stroke-width', 1.2);

    lbl(grp as Sel, bx + barW / 2, maxH + 10, `h${h}`, { size: 7, weight: '600', color });
    lbl(grp as Sel, bx + barW / 2, maxH - bh - 6, slope.toFixed(3), { size: 6, font: 'monospace', color });
  }
  lbl(grp as Sel, nHeads * (barW + barGap) / 2, maxH + 24, 'head index →  (steeper slope = attend more locally)', { size: 7, color: 'var(--text-muted)' });
}

function drawBiasMatrix(
  g: Gsel, x: number, y: number, size: number, cellW: number, slope: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      const dist = Math.abs(r - c);
      const bias = -slope * dist;
      const maxBias = slope * (size - 1);
      const norm = maxBias > 0 ? bias / maxBias : 0;
      grp.append('rect').attr('x', c * cellW).attr('y', r * cellW)
        .attr('width', cellW).attr('height', cellW)
        .attr('fill', hexA('#d97706', Math.abs(norm) * 0.8))
        .attr('stroke', 'var(--border)').attr('stroke-width', 0.3);
      if (cellW >= 18 && dist <= 2) {
        lbl(grp as Sel, c * cellW + cellW / 2, r * cellW + cellW / 2,
          bias.toFixed(1), { size: 5, font: 'monospace', color: norm < -0.3 ? '#fff' : 'var(--text)' });
      }
    }
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// Learned
// ══════════════════════════════════════════════════════════════════════════════

function renderLearned(g: Gsel, seqLen: number, dModel: number, W: number)
  : { width: number; height: number; steps: PEStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Positional Encoding — Learned', `d_model=${dModel}  seq_len=${seqLen}  max_seq=2048`);

  drawTensor(g as unknown as Sel, cx - 110, y, 220, 28, `x: [B, ${seqLen}, ${dModel}]`, '#e3f2fd', '#1976d2');
  y += 48;

  // Step 1: Position IDs
  const s1 = g.append('g').attr('class', 'step-node step-learned-ids').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 130, y, 260, 40, 'Position IDs', { step: 1, fill: '#e3f2fd', stroke: '#1976d2', formula: 'pos = [0, 1, 2, ..., seq-1]' });
  y += 56;

  const idCellW = 32, nIds = 10;
  const idX0 = cx - (nIds * idCellW) / 2;
  for (let i = 0; i < nIds; i++) {
    const ix = idX0 + i * idCellW;
    s1.append('rect').attr('x', ix).attr('y', y).attr('width', idCellW).attr('height', 24).attr('rx', 3)
      .attr('fill', hexA('#1976d2', 0.08)).attr('stroke', '#1976d2').attr('stroke-width', 1);
    lbl(s1 as Sel, ix + idCellW / 2, y + 12, `${i}`, { size: 9, weight: '600', color: '#1976d2' });
  }
  lbl(s1 as Sel, idX0 + nIds * idCellW + 10, y + 12, '...', { size: 12, color: 'var(--text-muted)' });
  y += 44;

  // Step 2: PE matrix lookup
  const s2 = g.append('g').attr('class', 'step-node step-learned-lookup').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 40, 'Position Embedding Lookup', { step: 2, fill: '#dcfce7', stroke: '#16a34a', formula: `P: [max_seq, ${dModel}]` });
  y += 56;

  // Matrix
  const matCols = 8, matRows = 10, matCellW = 24, matCellH = 18;
  const matX = cx - 160;
  const matGrp = s2.append('g').attr('transform', `translate(${matX},${y})`);
  const rand = makeLcg(555);
  for (let r = 0; r < matRows; r++) {
    const isHl = r < 4;
    for (let c = 0; c < matCols; c++) {
      const v = rand() * 2 - 1;
      const color = isHl ? '#16a34a' : '#94a3b8';
      matGrp.append('rect').attr('x', c * matCellW).attr('y', r * matCellH)
        .attr('width', matCellW).attr('height', matCellH)
        .attr('fill', hexA(color, isHl ? 0.12 + Math.abs(v) * 0.3 : 0.04))
        .attr('stroke', 'var(--border)').attr('stroke-width', 0.3);
    }
    lbl(matGrp as Sel, -8, r * matCellH + matCellH / 2, `${r}`, { size: 7, color: isHl ? '#16a34a' : 'var(--text-muted)', anchor: 'end', weight: isHl ? '700' : '400' });
    if (isHl) {
      matGrp.append('rect').attr('y', r * matCellH).attr('width', matCols * matCellW).attr('height', matCellH)
        .attr('fill', 'none').attr('stroke', '#16a34a').attr('stroke-width', 1.2);
    }
  }
  lbl(matGrp as Sel, matCols * matCellW / 2, -10, `P  [2048 × ${dModel}]`, { size: 9, weight: '700', color: '#16a34a' });
  lbl(matGrp as Sel, matCols * matCellW / 2, matRows * matCellH + 12, 'd_model →', { size: 7, color: '#16a34a', weight: '600' });
  lbl(matGrp as Sel, -20, matRows * matCellH / 2, 'max_seq ↑', { size: 7, color: '#16a34a', anchor: 'middle', weight: '600' });

  // Param badge
  const badgeX = matX + matCols * matCellW + 40;
  s2.append('rect').attr('x', badgeX).attr('y', y + 20).attr('width', 160).attr('height', 40).attr('rx', 6)
    .attr('fill', hexA('#16a34a', 0.06)).attr('stroke', '#16a34a').attr('stroke-width', 1);
  lbl(s2 as Sel, badgeX + 80, y + 34, 'Parameters', { size: 8, weight: '700', color: '#16a34a' });
  lbl(s2 as Sel, badgeX + 80, y + 48, `${fmtNum(2048 * dModel)}`, { size: 10, weight: '700', color: '#16a34a', font: 'monospace' });
  y += matRows * matCellH + 30;

  // Step 3: Addition
  const s3 = g.append('g').attr('class', 'step-node step-learned-add').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 140, y, 280, 40, 'Add to Token Embeddings', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'x = e + P[pos]' });
  y += 56;

  drawTensor(g as unknown as Sel, cx - 130, y, 260, 28, `out: [B, ${seqLen}, ${dModel}]`, '#fef3c7', '#d97706');
  y += 48;

  lbl(g, cx, y, `Params: max_seq × d_model = ${fmtNum(2048 * dModel)}`, { size: 10, color: '#16a34a', weight: '600' });
  y += 24;

  y = drawExplanation(g as Sel, 60, y, W - 120,
    'Learned positional encodings are fully trainable but cannot generalize beyond max_seq. ' +
    'Used in BERT and GPT-2. Modern models (Llama, Mistral) prefer RoPE for its length extrapolation.',
    'insight');
  y += 6;

  y = drawCodeAnnotation(g as Sel, 60, y, W - 120,
    'Learned Positional Encoding',
    ['Trainable embedding table indexed by position.', `Parameters: ${fmtNum(2048 * dModel)}.`],
    ['self.pos_embed = nn.Embedding(max_seq, d_model)', 'pe = self.pos_embed(pos)', 'x = token_embed + pe']);

  return { width: W, height: y + 20, steps: LEARNED_STEPS };
}

// ══════════════════════════════════════════════════════════════════════════════
// YaRN
// ══════════════════════════════════════════════════════════════════════════════

function renderYaRN(g: Gsel, seqLen: number, dModel: number, W: number)
  : { width: number; height: number; steps: PEStep[] } {
  const cx = W / 2;
  let y = 28;
  const base = 10000;
  const scaleFactor = 32;

  y = drawHeader(g, cx, y, 'Positional Encoding — YaRN', `d_model=${dModel}  scale=${scaleFactor}×  (4K → ${fmtNum(4096 * scaleFactor)})`);

  drawTensor(g as unknown as Sel, cx - 110, y, 220, 28, `q, k: [B, ${seqLen}, ${dModel}]`, '#e3f2fd', '#1976d2');
  y += 48;

  // Step 1: Original frequencies
  const s1 = g.append('g').attr('class', 'step-node step-yarn-orig').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 140, y, 280, 40, 'Original RoPE Frequencies', { step: 1, fill: '#e3f2fd', stroke: '#1976d2', formula: 'θ_i = base^(-2i/d)' });
  y += 56;

  drawFreqBars(s1, cx - 200, y, dModel, base, '#1976d2', 'Original (4K context)');
  y += 80;

  // Step 2: NTK scaling
  const s2 = g.append('g').attr('class', 'step-node step-yarn-ntk').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 40, 'NTK-Aware Base Scaling', { step: 2, fill: '#ede9fe', stroke: '#7c3aed', formula: `base_new = base · ${scaleFactor}^(d/(d-2))` });
  y += 56;

  drawFreqBarsComparison(s2, cx - 200, y, dModel, base, scaleFactor);
  y += 90;

  // Step 3: Dynamic scaling
  const s3 = g.append('g').attr('class', 'step-node step-yarn-dynamic').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 40, 'Dynamic Per-Dimension Scaling', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'interpolate low-freq, keep high-freq' });
  y += 56;

  drawDynamicScaling(s3, cx - 200, y, dModel, base, scaleFactor);
  y += 80;

  // Step 4: Temperature + rotation
  const s4 = g.append('g').attr('class', 'step-node step-yarn-rotate').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 40, 'Temperature-Scaled Rotation', { step: 4, fill: '#fee2e2', stroke: '#dc2626', formula: 'q_rot = t · R(θ_scaled · pos) · q' });
  y += 56;

  // Small rotation diagram with temperature
  const tempVal = Math.sqrt(1 + 0.1 * Math.log(scaleFactor));
  const planeR = 40;
  draw2DPlane(s4, cx - 70, y + planeR + 4, planeR, 0.5, 0.5 + 0.8, 'scaled rotation', 0.4);
  lbl(s4 as Sel, cx + 60, y + planeR, `t = √(1 + 0.1·ln(${scaleFactor}))`, { size: 8, font: 'monospace', color: '#dc2626', weight: '600', anchor: 'start' });
  lbl(s4 as Sel, cx + 60, y + planeR + 14, `t ≈ ${tempVal.toFixed(3)}`, { size: 9, font: 'monospace', color: '#dc2626', weight: '700', anchor: 'start' });
  y += planeR * 2 + 30;

  drawTensor(g as unknown as Sel, cx - 130, y, 260, 28, `q_rot, k_rot: [B, ${seqLen}, ${dModel}]`, '#fee2e2', '#dc2626');
  y += 48;

  lbl(g, cx, y, 'Params: 0 (frequency rescaling, no learnable parameters)', { size: 10, color: '#7c3aed', weight: '600' });
  y += 24;

  y = drawExplanation(g as Sel, 60, y, W - 120,
    `YaRN extends RoPE from ${fmtNum(4096)} to ${fmtNum(4096 * scaleFactor)} context by rescaling frequencies. ` +
    'NTK-aware scaling stretches wavelengths uniformly, while dynamic scaling preserves high-frequency ' +
    'dimensions that encode local position. Temperature correction maintains attention entropy.',
    'insight');
  y += 6;

  y = drawCodeAnnotation(g as Sel, 60, y, W - 120,
    'YaRN — Yet another RoPE extensioN (Peng et al. 2023)',
    [`Extends ${fmtNum(4096)}-trained context to ${fmtNum(4096 * scaleFactor)} tokens.`,
     'NTK base scaling + dynamic per-dim + temperature.'],
    [`s = ${scaleFactor}  # target_len / train_len`,
     `base_new = base * s ** (d / (d-2))`,
     'theta_scaled = 1.0 / (base_new ** (2i/d))',
     `t = sqrt(1 + 0.1 * log(${scaleFactor}))`,
     'q_rot = t * apply_rope(q, theta_scaled, pos)']);

  return { width: W, height: y + 20, steps: YARN_STEPS };
}

function drawFreqBars(
  g: Gsel, x: number, y: number, dModel: number, base: number,
  color: string, label: string,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const nBars = 12;
  const barH = 14, barGap = 3, maxW = 300;

  for (let i = 0; i < nBars; i++) {
    const theta = Math.pow(base, -2 * i / dModel);
    const logVal = (Math.log10(theta) + 5) / 5;
    const bw = Math.max(4, maxW * logVal);
    const by = i * (barH + barGap);

    grp.append('rect').attr('x', 0).attr('y', by).attr('width', bw).attr('height', barH).attr('rx', 2)
      .attr('fill', hexA(color, 0.25)).attr('stroke', color).attr('stroke-width', 0.8);
    lbl(grp as Sel, -6, by + barH / 2, `i=${i}`, { size: 6, color, anchor: 'end' });
    const valStr = theta >= 0.001 ? theta.toFixed(4) : theta.toExponential(1);
    lbl(grp as Sel, bw + 4, by + barH / 2, valStr, { size: 6, font: 'monospace', color: 'var(--text-muted)', anchor: 'start' });
  }
  lbl(grp as Sel, maxW / 2, nBars * (barH + barGap) + 10, label, { size: 8, weight: '600', color });
}

function drawFreqBarsComparison(
  g: Gsel, x: number, y: number, dModel: number, base: number, scale: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const nBars = 10;
  const barH = 10, barGap = 5, maxW = 260;
  const newBase = base * Math.pow(scale, dModel / (dModel - 2));

  for (let i = 0; i < nBars; i++) {
    const thetaOrig = Math.pow(base, -2 * i / dModel);
    const thetaNew = Math.pow(newBase, -2 * i / dModel);
    const logOrig = (Math.log10(thetaOrig) + 5) / 5;
    const logNew = (Math.log10(thetaNew) + 5) / 5;
    const bwOrig = Math.max(4, maxW * logOrig);
    const bwNew = Math.max(4, maxW * logNew);
    const by = i * (barH * 2 + barGap);

    // Original (blue)
    grp.append('rect').attr('x', 0).attr('y', by).attr('width', bwOrig).attr('height', barH).attr('rx', 2)
      .attr('fill', hexA('#1976d2', 0.25)).attr('stroke', '#1976d2').attr('stroke-width', 0.6);
    // Scaled (purple)
    grp.append('rect').attr('x', 0).attr('y', by + barH + 1).attr('width', bwNew).attr('height', barH).attr('rx', 2)
      .attr('fill', hexA('#7c3aed', 0.25)).attr('stroke', '#7c3aed').attr('stroke-width', 0.6);

    lbl(grp as Sel, -6, by + barH, `i=${i}`, { size: 6, color: 'var(--text-muted)', anchor: 'end' });
  }
  // Legend
  const ly = nBars * (barH * 2 + barGap) + 4;
  grp.append('rect').attr('x', maxW + 20).attr('y', 0).attr('width', 14).attr('height', 10).attr('rx', 2)
    .attr('fill', hexA('#1976d2', 0.25)).attr('stroke', '#1976d2').attr('stroke-width', 0.6);
  lbl(grp as Sel, maxW + 38, 5, 'Original', { size: 7, color: '#1976d2', anchor: 'start' });
  grp.append('rect').attr('x', maxW + 20).attr('y', 16).attr('width', 14).attr('height', 10).attr('rx', 2)
    .attr('fill', hexA('#7c3aed', 0.25)).attr('stroke', '#7c3aed').attr('stroke-width', 0.6);
  lbl(grp as Sel, maxW + 38, 21, `Scaled (${scale}×)`, { size: 7, color: '#7c3aed', anchor: 'start' });
  lbl(grp as Sel, maxW / 2, ly + 6, `base: ${base} → ${fmtNum(Math.round(newBase))}`, { size: 8, weight: '600', color: '#7c3aed' });
}

function drawDynamicScaling(
  g: Gsel, x: number, y: number, dModel: number, base: number, scale: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const nBars = 10;
  const barH = 12, barGap = 4, maxW = 280;
  const newBase = base * Math.pow(scale, dModel / (dModel - 2));
  const boundary = Math.floor(nBars * 0.5);

  for (let i = 0; i < nBars; i++) {
    const isInterpolate = i >= boundary;
    const thetaOrig = Math.pow(base, -2 * i / dModel);
    const thetaScaled = Math.pow(newBase, -2 * i / dModel);
    const thetaFinal = isInterpolate ? thetaScaled : thetaOrig;
    const logVal = (Math.log10(thetaFinal) + 5) / 5;
    const bw = Math.max(4, maxW * logVal);
    const by = i * (barH + barGap);
    const color = isInterpolate ? '#7c3aed' : '#d97706';

    grp.append('rect').attr('x', 0).attr('y', by).attr('width', bw).attr('height', barH).attr('rx', 2)
      .attr('fill', hexA(color, 0.25)).attr('stroke', color).attr('stroke-width', 0.8);
    lbl(grp as Sel, -6, by + barH / 2, `i=${i}`, { size: 6, color: 'var(--text-muted)', anchor: 'end' });
    lbl(grp as Sel, bw + 6, by + barH / 2,
      isInterpolate ? 'interp' : 'keep',
      { size: 6, color, anchor: 'start', weight: '600' });
  }

  // Legend
  const ly = nBars * (barH + barGap) + 6;
  grp.append('rect').attr('x', maxW + 20).attr('y', 0).attr('width', 14).attr('height', 10).attr('rx', 2)
    .attr('fill', hexA('#7c3aed', 0.25)).attr('stroke', '#7c3aed').attr('stroke-width', 0.6);
  lbl(grp as Sel, maxW + 38, 5, 'Interpolate (low freq)', { size: 7, color: '#7c3aed', anchor: 'start' });
  grp.append('rect').attr('x', maxW + 20).attr('y', 16).attr('width', 14).attr('height', 10).attr('rx', 2)
    .attr('fill', hexA('#d97706', 0.25)).attr('stroke', '#d97706').attr('stroke-width', 0.6);
  lbl(grp as Sel, maxW + 38, 21, 'Keep original (high freq)', { size: 7, color: '#d97706', anchor: 'start' });
  lbl(grp as Sel, maxW / 2, ly, 'Low-freq dims scale for long context; high-freq dims preserve local attention', { size: 7, color: 'var(--text-muted)' });
}
